"use typeshade";
class Args { n: u32; }
class Item { f0: f32; f1: f32; f2: f32; f3: f32; f4: f32; f5: f32; f6: f32; f7: f32; }
declare const args: uniform<Args>;
declare const src: storage<array<Item>>;
declare const out: storage<array<f32>, "read_write">;

@compute([64])
export function main(@builtin("global_invocation_id") gid: vec3u): void {
 const i: u32 = gid.x;
 if (i >= args.n) { return; }
 out[i] = src[i].f0;
}

